            return "Failed"

        # Decode the message
        decoded_chars = []
        for c in message:
            if not c.isalpha():
                return "Failed"
            c_up = c.upper()
            if c_up not in mapping:
                return "Failed"
            decoded_chars.append(mapping[c_up])

        return "".join(decoded_chars)
    except Exception:
        return "Failed"

def min_remaining_space(V: int, n: int, volumes: list) -> int:
    """
    Calculate the minimum remaining space in a box after trying to fit a number of items with given volumes.

    This function uses a dynamic programming approach to determine the maximum volume that can be occupied
    in the box by any subset of the given items. It then returns the difference between the box's total capacity
    and this maximum occupied volume, which is the minimum remaining space.

    Args:
    - V (int): The total capacity of the box.
    - n (int): The number of items to consider for packing into the box.
    - volumes (List[int]): A list of the volumes of the n items.

    Returns:
    - int: The minimum remaining space in the box after fitting the items.
    """
    # Basic validation and edge cases
    try:
        if V < 0:
            return 0
        if n <= 0 or not volumes:
            return max(0, V)
        # In case the provided list is shorter/longer than n, we only use the first n valid integers
        volumes_to_use = [v for v in volumes[:n] if isinstance(v, int) and v >= 0]
        if not volumes_to_use:
            return max(0, V)
    except Exception:
        return max(0, V)

    # DP array: dp[s] is True if a subset of items can achieve total volume s
    dp = [False] * (V + 1)
    dp[0] = True
    best_sum = 0

    for vol in volumes_to_use:
        if vol > V:
            continue
        # Traverse backwards to avoid reusing the same item
        for s in range(V, vol - 1, -1):
            if dp[s - vol]:
                dp[s] = True
                if s > best_sum:
                    best_sum = s
                    # Early exit if perfect fit found
                    if best_sum == V:
                        return 0

    # In case the best sum was not found inside the loop, recompute in case dp[best] is True
    for s in range(V, -1, -1):
        if dp[s]:
            best_sum = s
            break

    remaining = V - best_sum
    return remaining if remaining >= 0 else 0

